import re, subprocess, os, shutil, sys, time, itertools, difflib

APP = '/app'
WORK = '/tmp/tb_search/work'
os.makedirs(WORK, exist_ok=True)
shutil.copy(APP + '/main.tex', WORK + '/main.tex')

# Load synonym families
syns = []
with open(APP + '/synonyms.txt') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        words = [w.strip() for w in line.split(',') if w.strip()]
        syns.append(words)

word2fam = {}
for i, fam in enumerate(syns):
    for w in fam:
        word2fam.setdefault(w, []).append(i)

text = open(APP + '/input.tex').read()

def get_tokens(t):
    toks = []
    for m in re.finditer(r'[A-Za-z]+', t):
        w = m.group(0)
        if w in word2fam:
            toks.append((m.start(), m.end(), w))
    return toks

def compile_check(cand_text):
    with open(WORK + '/input.tex', 'w') as f:
        f.write(cand_text)
    r = subprocess.run(['pdflatex', '-interaction=nonstopmode', 'main.tex'],
                       cwd=WORK, capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError('pdflatex failed: ' + r.stdout[-2000:] + r.stderr[-2000:])
    log = open(WORK + '/main.log').read()
    overs = re.findall(r'Overfull \\hbox \(([\d.]+)pt too wide\) in paragraph at lines ([0-9\-]+)', log)
    total = sum(float(x) for x, _ in overs)
    return len(overs), total, overs

def case_ok(w, r):
    if w[0].isupper() != r[0].isupper():
        return False
    if w.isupper() != r.isupper():
        return False
    return True

def candidate_repl(w):
    out = []
    for i in word2fam[w]:
        for r in syns[i]:
            if r == w:
                continue
            if case_ok(w, r):
                out.append(r)
    return out

def apply_changes(cur_text, changes):
    # changes: list of (start, end, newword); apply from the end
    for s, e, r in sorted(changes, reverse=True):
        cur_text = cur_text[:s] + r + cur_text[e:]
    return cur_text

def main():
    t0 = time.time()
    cur_text = text
    overs, total, det = compile_check(cur_text)
    print(f"initial: {overs} overfull, total={total:.3f}pt", flush=True)
    for (w, l) in det:
        print(f"  {w}pt @ lines {l}", flush=True)
    while overs > 0:
        toks = get_tokens(cur_text)
        best = None
        for (s, e, w) in toks:
            for r in candidate_repl(w):
                cand = apply_changes(cur_text, [(s, e, r)])
                o, tot, _ = compile_check(cand)
                if best is None or (o, tot) < (best[0][0], best[0][1]):
                    best = ((o, tot), cand, (w, r))
        if best is not None and (best[0][0], best[0][1]) < (overs, total):
            (o, tot), cand, (w, r) = best
            print(f"  change {w!r}->{r!r}: now {o} overfull, total={tot:.3f}pt  (elapsed {time.time()-t0:.0f}s)", flush=True)
            cur_text = cand
            overs, total, det = compile_check(cur_text)
            for (w, l) in det:
                print(f"    remaining {w}pt @ lines {l}", flush=True)
            continue
        # Stuck with single changes -> try pairs within same paragraph of worst overfull
        print("  stuck on singles; trying pairs", flush=True)
        if not det:
            print("STUCK no overfull info", flush=True); sys.exit(1)
        worst_w = max(float(x) for x, _ in det)
        worst_lines = [l for (x, l) in det if float(x) == worst_w][0]
        # paragraph = contiguous nonempty lines around worst lines range
        lines = cur_text.split('\n')
        lo, hi = (int(x) - 1 for x in worst_lines.split('--'))
        pstart = hi  # start of paragraph: go up to blank line
        while pstart > 0 and lines[pstart - 1].strip() != '':
            pstart -= 1
        pend = lo  # end of paragraph: go down to blank line
        while pend < len(lines) - 1 and lines[pend + 1].strip() != '':
            pend += 1
        span_start = sum(len(lines[k]) + 1 for k in range(pstart))
        span_end = sum(len(lines[k]) + 1 for k in range(pend)) + len(lines[pend])
        ptoks = [(s, e, w) for (s, e, w) in toks if span_start <= s < span_end]
        print(f"  worst paragraph lines {pstart+1}-{pend+1}, {len(ptoks)} candidate words, {len(ptoks)*max(len(candidate_repl(w)) for _,_,w in ptoks) if ptoks else 0} pair-combos (approx)", flush=True)
        best = None
        for (s1, e1, w1), (s2, e2, w2) in itertools.combinations(ptoks, 2):
            for r1 in candidate_repl(w1):
                for r2 in candidate_repl(w2):
                    cand = apply_changes(cur_text, [(s1, e1, r1), (s2, e2, r2)])
                    o, tot, _ = compile_check(cand)
                    if best is None or (o, tot) < (best[0][0], best[0][1]):
                        best = ((o, tot), cand, (w1, r1, w2, r2))
        if best is not None and (best[0][0], best[0][1]) < (overs, total):
            (o, tot), cand, (w1, r1, w2, r2) = best
            print(f"  pair change {w1!r}->{r1!r}, {w2!r}->{r2!r}: now {o} overfull, total={tot:.3f}pt (elapsed {time.time()-t0:.0f}s)", flush=True)
            cur_text = cand
            overs, total, det = compile_check(cur_text)
            for (w, l) in det:
                print(f"    remaining {w}pt @ lines {l}", flush=True)
            continue
        print("STUCK: no improving pair found", flush=True)
        sys.exit(1)
    print(f"DONE: zero overfull hboxes. elapsed {time.time()-t0:.0f}s", flush=True)
    with open(APP + '/input.tex', 'w') as f:
        f.write(cur_text)
    ot = [m.group(0) for m in re.finditer(r'[A-Za-z]+', text)]
    nt = [m.group(0) for m in re.finditer(r'[A-Za-z]+', cur_text)]
    sm = difflib.SequenceMatcher(a=ot, b=nt)
    changes = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'replace':
            for a, b in zip(ot[i1:i2], nt[j1:j2]):
                changes.append((a, b))
    print("Changes made:", flush=True)
    for a, b in changes:
        fams = word2fam.get(a, [])
        ok = any(b in syns[i] for i in fams)
        print(f"  {a!r} -> {b!r}  family_ok={ok}", flush=True)
        if not ok:
            sys.exit(2)

