use strict;
use warnings;

my $APP = '/app';
my $WORK = '/tmp/tb_search/work';
mkdir($WORK) unless -d $WORK;
{
    open(my $a, '<', "$APP/main.tex") or die "no main.tex: $!";
    local $/; my $m = <$a>; close($a);
    open(my $o, '>', "$WORK/main.tex") or die $!;
    print $o $m; close($o);
}

# Load synonym families
my @syns;
open(my $sf, '<', "$APP/synonyms.txt") or die $!;
while (my $line = <$sf>) {
    $line =~ s/^\s+//; $line =~ s/\s+$//;
    next if $line eq '';
    my @words = map { s/^\s+//; s/\s+$//; $_ } split(',', $line);
    push @syns, [grep { length } @words];
}
close($sf);

my %word2fam;
for my $i (0 .. $#syns) {
    for my $w (@{$syns[$i]}) {
        push @{$word2fam{$w}}, $i;
    }
}

open(my $tf, '<', "$APP/input.tex") or die $!;
local $/; my $text = <$tf>; close($tf);

sub get_tokens {
    my ($t) = @_;
    my @toks;
    while ($t =~ /([A-Za-z]+)/g) {
        my $w = $1;
        push @toks, [pos($t) - length($w), pos($t), $w] if exists $word2fam{$w};
    }
    return @toks;
}

sub compile_check {
    my ($cand) = @_;
    open(my $o, '>', "$WORK/input.tex") or die $!;
    print $o $cand; close($o);
    my $out = `cd $WORK && pdflatex -interaction=nonstopmode main.tex 2>&1`;
    my $rc = $?;
    die "pdflatex failed:\n$out" if $rc != 0;
    open(my $lf, '<', "$WORK/main.log") or die "no log: $!";
    local $/; my $log = <$lf>; close($lf);
    my @overs;
    while ($log =~ /Overfull \\hbox \(([\d.]+)pt too wide\) in paragraph at lines ([\d\-]+)/g) {
        push @overs, [$1, $2];
    }
    my $total = 0; $total += $_->[0] for @overs;
    return (scalar(@overs), $total, \@overs);
}

sub case_ok {
    my ($w, $r) = @_;
    return 0 if ($w =~ /^[A-Z]/) != ($r =~ /^[A-Z]/);
    return 0 if ($w =~ /^[A-Z]+$/) != ($r =~ /^[A-Z]+$/);
    return 1;
}

sub candidate_repl {
    my ($w) = @_;
    my @out;
    for my $i (@{$word2fam{$w}}) {
        for my $r (@{$syns[$i]}) {
            next if $r eq $w;
            push @out, $r if case_ok($w, $r);
        }
    }
    return @out;
}

sub apply_changes {
    my ($t, $changes) = @_;
    for my $c (sort { $b->[0] <=> $a->[0] } @$changes) {
        my ($s, $e, $r) = @$c;
        $t = substr($t, 0, $s) . $r . substr($t, $e);
    }
    return $t;
}

my $cur = $text;
my ($overs, $total, $det) = compile_check($cur);
printf "initial: %d overfull, total=%.3fpt\n", $overs, $total;
printf "  %spt @ lines %s\n", @$_ for @$det;

my $guard = 0;
while ($overs > 0) {
    die "guard" if ++$guard > 30;
    my @toks = get_tokens($cur);
    my $best;
    for my $tok (@toks) {
        my ($s, $e, $w) = @$tok;
        for my $r (candidate_repl($w)) {
            my $cand = apply_changes($cur, [[$s, $e, $r]]);
            my ($o, $tot) = compile_check($cand);
            if (!defined $best || ($o, $tot) < ($best->[0], $best->[1])) {
                $best = [[$o, $tot], $cand, $w, $r];
            }
        }
    }
    if (defined $best && ($best->[0][0], $best->[0][1]) < ($overs, $total)) {
        my ($o, $tot) = @{$best->[0]};
        printf "  change %s -> %s : now %d overfull, total=%.3fpt\n", $best->[2], $best->[3], $o, $tot;
        $cur = $best->[1];
        ($overs, $total, $det) = compile_check($cur);
        printf "    remaining %spt @ lines %s\n", @$_ for @$det;
        next;
    }
    print "  stuck on singles; trying pairs\n";
    die "no overfull info" unless @$det;
    my $worst = 0;
    $worst = $_->[0] if $_->[0] > $worst for @$det;
    my $worst_lines = (grep { $_->[0] == $worst } @$det)[0][1];
    my @lines = split("\n", $cur, -1);
    my @lr = split('--', $worst_lines);
    my ($lo, $hi) = ($lr[0] - 1, $lr[1] - 1);
    my $pstart = $hi;
    $pstart-- while $pstart > 0 && $lines[$pstart-1] =~ /\S/;
    my $pend = $lo;
    $pend++ while $pend < $#lines && $lines[$pend+1] =~ /\S/;
    my $span_start = 0;
    $span_start += length($lines[$_]) + 1 for 0 .. $pstart-1;
    my $span_end = $span_start;
    $span_end += length($lines[$_]) + 1 for $pstart .. $pend-1;
    $span_end += length($lines[$pend]);
    my @ptoks = grep { $_->[0] >= $span_start && $_->[0] < $span_end } @toks;
    printf "  worst paragraph lines %d-%d, %d candidate words\n", $pstart+1, $pend+1, scalar(@ptoks);
    $best = undef;
    for my $i (0 .. $#ptoks) {
        for my $j ($i+1 .. $#ptoks) {
            my ($s1, $e1, $w1) = @{$ptoks[$i]};
            my ($s2, $e2, $w2) = @{$ptoks[$j]};
            for my $r1 (candidate_repl($w1)) {
                for my $r2 (candidate_repl($w2)) {
                    my $cand = apply_changes($cur, [[$s1, $e1, $r1], [$s2, $e2, $r2]]);
                    my ($o, $tot) = compile_check($cand);
                    if (!defined $best || ($o, $tot) < ($best->[0], $best->[1])) {
                        $best = [[$o, $tot], $cand, $w1, $r1, $w2, $r2];
                    }
                }
            }
        }
    }
    if (defined $best && ($best->[0][0], $best->[0][1]) < ($overs, $total)) {
        my ($o, $tot) = @{$best->[0]};
        printf "  pair change %s -> %s, %s -> %s : now %d overfull, total=%.3fpt\n", $best->[2], $best->[3], $best->[4], $best->[5], $o, $tot;
        $cur = $best->[1];
        ($overs, $total, $det) = compile_check($cur);
        printf "    remaining %spt @ lines %s\n", @$_ for @$det;
        next;
    }
    die "STUCK: no improving pair found";
}

print "DONE: zero overfull hboxes\n";
open(my $of, '>', "$APP/input.tex") or die $!;
print $of $cur; close($of);

# Report changes
my @ot = $text =~ /([A-Za-z]+)/g;
my @nt = $cur =~ /([A-Za-z]+)/g;
# align via simple two-pointer since only single-word replacements
my ($i, $j) = (0, 0);
my $ok_all = 1;
while ($i < @ot && $j < @nt) {
    if ($ot[$i] eq $nt[$j]) { $i++; $j++; }
    else {
        my ($a, $b) = ($ot[$i], $nt[$j]);
        my $ok = 0;
        for my $fi (@{$word2fam{$a} // []}) { $ok = 1 if grep { $_ eq $b } @{$syns[$fi]}; }
        printf "  %s -> %s  family_ok=%d\n", $a, $b, $ok;
        $ok_all = 0 unless $ok;
        $i++; $j++;
    }
}
die "some change not in family" unless $ok_all;
print "All changes validated against synonym families.\n";

