    return 0 unless defined $b;
    return 1 if $a->[0] < $b->[0];
    return 0 if $a->[0] > $b->[0];
    return $a->[1] < $b->[1];
}

sub case_ok {
    my ($w, $r) = @_;
    return 0 if ($w =~ /^[A-Z]/) != ($r =~ /^[A-Z]/);
    return 0 if ($w =~ /^[A-Z]+$/) != ($r =~ /^[A-Z]+$/);
    return 1;
}

sub candidate_repl {
    my ($w) = @_;
