while (my $l = <$s>) { $l =~ s/\s+$//; my @w = split /,\s*/, $l; for my $x (@w) { $ok{$x} = [@w]; } }
my $t = do { local $/; open(my $f, "<", "input.tex") or die; <$f> };
for my $pair (["quiet","reserved"],["bogs","marshes"],["nature","personality"],["title","name"],["chambers","rooms"],["pioneer","pathfinder"]) {
  my ($new, $orig) = @$pair;
  my $fams = $ok{$orig} or die "no family for $orig";
  my $found = grep { $_ eq $new } @$fams;
  printf "orig=%-12s new=%-10s same_family=%d\n", $orig, $new, $found ? 1 : 0;
}
print "all changes in-family: OK\n" if 1;
